    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    out = [row[:] for row in grid]
    for r, c in sixes:
        out[r][c] = 0

    if not fours or not sixes:
        return out

    rmin = min(r for r, c in fours)
    rmax = max(r for r, c in fours)
    cmin = min(c for r, c in fours)
    cmax = max(c for r, c in fours)

    srmin = min(r for r, c in sixes)
    srmax = max(r for r, c in sixes)

    # An extreme full row on the 6-shape indicates a horizontal reflection;
    # otherwise its full middle row indicates a vertical reflection.
    six_cols = [c for r, c in sixes]
    six_rows = [r for r, c in sixes]
    horizontal = False
    for rr in (srmin, srmax):
        if all((rr, c) in set(sixes) for c in range(min(six_cols), max(six_cols) + 1)):
            horizontal = True
            break

    if horizontal:
        six_center_c = sum(c for r, c in sixes) / len(sixes)
        four_center_c = sum(c for r, c in fours) / len(fours)
        preferred_right = six_center_c < four_center_c

        def valid_right():
            return all(2 * cmax + 1 - c < w for r, c in fours)

        def valid_left():
            return all(2 * cmin - 1 - c >= 0 for r, c in fours)

        go_right = preferred_right
        if go_right and not valid_right():
            go_right = False
        elif not go_right and not valid_left():
            go_right = True

        for r, c in fours:
            nc = 2 * cmax + 1 - c if go_right else 2 * cmin - 1 - c
            if 0 <= nc < w:
                out[r][nc] = 4
    else:
        six_center_r = sum(r for r, c in sixes) / len(sixes)
        four_center_r = sum(r for r, c in fours) / len(fours)
        preferred_down = six_center_r < four_center_r

        def valid_down():
            return all(2 * rmax + 1 - r < h for r, c in fours)

        def valid_up():
            return all(2 * rmin - 1 - r >= 0 for r, c in fours)

        go_down = preferred_down
        if go_down and not valid_down():
            go_down = False
        elif not go_down and not valid_up():
            go_down = True

        for r, c in fours:
            nr = 2 * rmax + 1 - r if go_down else 2 * rmin - 1 - r
            if 0 <= nr < h:
                out[nr][c] = 4

    return out
